public class RawInputChecks{public static class Mouse{int action,button;Mouse(int a,int b){action=a;button=b;}public int getAction(){return action;}public int getButton(){return button;}}public static void main(String[]a){Minecraft mc=Minecraft.INSTANCE;ServerPlayer p=new ServerPlayer();mc.player=p;final long[]now={1_000_000_000L};BoxingClient16.CLOCK=()->now[0];BoxingClient16.mouse(new Mouse(1,0));now[0]+=10_000_000L;BoxingClient16.mouse(new Mouse(0,0));now[0]+=85_000_000L;Hand hand=new Hand();BoxingClient16.hand(hand);if(!hand.canceled||hand.buffers.flushes!=1||Math.abs(hand.pose.translations.get(2)[2]+.1)<.1)throw new AssertionError("quick press/release between ticks must render and flush a punch");double x=p.x,y=p.y,z=p.z;p.main=new Stack(false);Hand weapon=new Hand();BoxingClient16.hand(weapon);if(weapon.canceled||p.x!=x||p.y!=y||p.z!=z)throw new AssertionError("weapon handoff/movement");System.out.println("RAW_CLICK_BETWEEN_TICKS_BUFFER_FLUSH_WEAPON_HANDOFF_CHECKS=3");}}
